    // Lane dashes.
    ctx.fillStyle = PALETTE.lane;
    for (const rx of V_ROADS) {
      for (let y = 40; y < BEACH_Y; y += 64) ctx.fillRect(rx - 2, y, 4, 30);
    }
    for (const ry of H_ROADS) {
